-- Read-only baseline extracted from TESTE on 2026-08-13.
-- Source: Resultado_da_Query (24).xlsx; do not edit as deployment source.
CREATE OR REPLACE PROCEDURE STP_ATUALIZA_PROV_FILA_PRA   AS
V_SEQPREV INT;
BEGIN

FOR PROD IN (SELECT  CODPROD, NUNOTA, SEQUENCIA, PROVISAO
FROM AD_TGFSEQENT E
WHERE NVL(PROVISAO,'N') = 'S' AND TRUNC(DTPREV - SYSDATE) <= 120
ORDER BY E.SEQENT ) LOOP

--BUSCA A PROXIMA SEQUENCIA NA FILA
SELECT NVL(MAX(SEQENT),0) + 10
INTO V_SEQPREV
FROM AD_TGFSEQENT E
WHERE E.CODPROD = PROD.CODPROD;

-- Inserção ou atualização da sequência
UPDATE AD_TGFSEQENT
SET PROVISAO = 'N'
,SEQENT = V_SEQPREV
WHERE NVL(PROVISAO,'N') = 'S'
AND CODPROD = PROD.CODPROD
AND NUNOTA = PROD.NUNOTA
AND SEQUENCIA = PROD.SEQUENCIA ;

END LOOP;
END STP_ATUALIZA_PROV_FILA_PRA;

/
